using Appizza.BuildingBlocks;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Appizza.Modules.Ordering;
public static class Phase5CancellationPermissions { public static readonly string[] All = ["ordering.order_item_request.view", "ordering.order_item_request.decide", "ordering.order_item.cancel_ready", "kitchen.order_item_request.decide"]; }
public sealed class OrderItemRequest : IVersionedEntity { public Guid Id { get; set; } public Guid EstablishmentId { get; set; } public Guid OrderId { get; set; } public Guid OrderItemId { get; set; } public string RequestType { get; set; } = "cancel"; public string? RequestedConfiguration { get; set; } public string? ReviewedSnapshot { get; set; } public string? ReviewHash { get; set; } public int? CustomerConfirmedVersion { get; set; } public DateTimeOffset? CustomerConfirmedAt { get; set; } public string ReasonCode { get; set; } = null!; public string? CustomerNote { get; set; } public string Status { get; set; } = "pending_validation"; public string? RequiredApprovalLevel { get; set; } public decimal PriceDifference { get; set; } public string Source { get; set; } = "customer"; public int RequestVersion { get; set; } = 1; public int OriginalRevisionNumber { get; set; } public Guid? RequestedByDeviceId { get; set; } public Guid? RequestedByUserId { get; set; } public DateTimeOffset RequestedAt { get; set; } public DateTimeOffset? WithdrawnAt { get; set; } public DateTimeOffset? DecidedAt { get; set; } public Guid? DecidedByUserId { get; set; } public Guid? DecidedByDeviceId { get; set; } public string? DecisionReason { get; set; } public string? ProductionAction { get; set; } public long Version { get; set; } }
public sealed class OrderItemRevision { public Guid Id { get; set; } public Guid EstablishmentId { get; set; } public Guid OrderItemId { get; set; } public int RevisionNumber { get; set; } public Guid SourceRequestId { get; set; } public string Snapshot { get; set; } = null!; public int SnapshotSchemaVersion { get; set; } = 1; public string Configuration { get; set; } = null!; public decimal PreviousUnitAmount { get; set; } public decimal UnitAmount { get; set; } public decimal PreviousTotalAmount { get; set; } public decimal TotalAmount { get; set; } public decimal PriceDifference { get; set; } public Guid CatalogRevisionId { get; set; } public long CatalogVersion { get; set; } public long AvailabilityVersion { get; set; } public string ConfigurationVersion { get; set; } = null!; public DateTimeOffset EffectiveAt { get; set; } public Guid? EffectiveByUserId { get; set; } public Guid? EffectiveByDeviceId { get; set; } public string Origin { get; set; } = null!; public DateTimeOffset CreatedAt { get; set; } }
public sealed class OrderStatusHistory { public Guid Id { get; set; } public Guid OrderId { get; set; } public string? PreviousStatus { get; set; } public string NewStatus { get; set; } = null!; public string? SubstatusCode { get; set; } public string? CustomerMessage { get; set; } public string? Reason { get; set; } public DateTimeOffset ChangedAt { get; set; } public Guid? CorrelationId { get; set; } }
public sealed class OrderItemRequestConfiguration : IEntityTypeConfiguration<OrderItemRequest> { public void Configure(EntityTypeBuilder<OrderItemRequest> builder) { builder.ToTable("order_item_request", "ordering", t => { t.HasCheckConstraint("ck_order_item_request_type", "request_type in ('cancel','change')"); t.HasCheckConstraint("ck_order_item_request_status", "status in ('pending_validation','pending_customer_confirmation','pending_operational_decision','approved','rejected','withdrawn','expired')"); t.HasCheckConstraint("ck_order_item_request_production_action", "production_action is null or production_action in ('continue','restart','reject')"); t.HasCheckConstraint("ck_order_item_request_cancellation_shape", "request_type <> 'cancel' or (requested_configuration is null and price_difference = 0)"); }); builder.HasKey(x => x.Id); builder.Property(x => x.RequestType).HasMaxLength(20); builder.Property(x => x.RequestedConfiguration).HasColumnType("jsonb"); builder.Property(x => x.ReviewedSnapshot).HasColumnType("jsonb"); builder.Property(x => x.ReviewHash).HasMaxLength(128); builder.Property(x => x.ReasonCode).HasMaxLength(80); builder.Property(x => x.Status).HasMaxLength(40); builder.Property(x => x.RequiredApprovalLevel).HasMaxLength(40); builder.Property(x => x.PriceDifference).HasPrecision(14, 2); builder.Property(x => x.Source).HasMaxLength(40); builder.Property(x => x.DecisionReason).HasMaxLength(1000); builder.Property(x => x.ProductionAction).HasMaxLength(20); builder.Property(x => x.Version).IsConcurrencyToken(); builder.HasIndex(x => new { x.EstablishmentId, x.Status, x.RequestedAt }); builder.HasIndex(x => x.OrderItemId).IsUnique().HasFilter("status in ('pending_validation','pending_customer_confirmation','pending_operational_decision')"); } }
public sealed class OrderItemRevisionConfiguration : IEntityTypeConfiguration<OrderItemRevision> { public void Configure(EntityTypeBuilder<OrderItemRevision> builder) { builder.ToTable("order_item_revision", "ordering", t => { t.HasCheckConstraint("ck_order_item_revision_number", "revision_number > 0"); t.HasCheckConstraint("ck_order_item_revision_amounts", "previous_unit_amount >= 0 and unit_amount >= 0 and previous_total_amount >= 0 and total_amount >= 0"); t.HasCheckConstraint("ck_order_item_revision_actor", "not (effective_by_user_id is not null and effective_by_device_id is not null)"); }); builder.HasKey(x => x.Id); builder.Property(x => x.Snapshot).HasColumnType("jsonb"); builder.Property(x => x.Configuration).HasColumnType("jsonb"); builder.Property(x => x.PreviousUnitAmount).HasPrecision(14,2); builder.Property(x => x.UnitAmount).HasPrecision(14,2); builder.Property(x => x.PreviousTotalAmount).HasPrecision(14,2); builder.Property(x => x.TotalAmount).HasPrecision(14,2); builder.Property(x => x.PriceDifference).HasPrecision(14,2); builder.Property(x => x.ConfigurationVersion).HasMaxLength(128); builder.Property(x => x.Origin).HasMaxLength(40); builder.HasIndex(x => new { x.OrderItemId, x.RevisionNumber }).IsUnique(); builder.HasIndex(x => x.SourceRequestId).IsUnique(); builder.HasIndex(x => new { x.EstablishmentId, x.OrderItemId, x.EffectiveAt }); } }
public sealed class OrderStatusHistoryConfiguration : IEntityTypeConfiguration<OrderStatusHistory> { public void Configure(EntityTypeBuilder<OrderStatusHistory> builder) { builder.ToTable("order_status_history", "ordering"); builder.HasKey(x => x.Id); builder.Property(x => x.PreviousStatus).HasMaxLength(40); builder.Property(x => x.NewStatus).HasMaxLength(40); builder.Property(x => x.SubstatusCode).HasMaxLength(80); builder.HasIndex(x => new { x.OrderId, x.ChangedAt }); } }
public static class CancellationPolicy { public static CancellationDisposition For(string? status) => status switch { null or "awaiting_acceptance" or "accepted" or "awaiting_preparation" => CancellationDisposition.Automatic, "in_preparation" or "paused" => CancellationDisposition.KitchenDecision, "ready" => CancellationDisposition.ManagerDecision, _ => CancellationDisposition.Forbidden }; public static string OrderStatus(int cancelled, int total) => cancelled == 0 ? "submitted" : cancelled == total ? "cancelled" : "partially_cancelled"; }
public enum CancellationDisposition { Automatic, KitchenDecision, ManagerDecision, Forbidden }
